#define LOG_TAG            "brilliance"
#define LOG_LVL            LOG_LVL_INFO

#include <rtthread.h>
#include <rtdevice.h>
#include <rtdbg.h>

#include "brilliance.h"
#include "../../light_sener/light_sener.h"

/* PWM设备名称 */
#define PWM_DEVICE_NAME    "pwm"

/* 默认最低亮度值（避免黑暗状态下屏幕全黑）*/
#define DEFAULT_MIN_BRIGHTNESS    5

/* 自动亮度调节线程优先级 */
#define AUTO_BRILLIANCE_THREAD_PRIORITY    10
#define AUTO_BRILLIANCE_THREAD_STACK_SIZE  1024
#define AUTO_BRILLIANCE_UPDATE_INTERVAL    2000    /* 2秒更新一次 */

/* 光感值范围映射 */
#define LIGHT_SENSOR_MIN         0
#define LIGHT_SENSOR_MAX         4095    /* 12位ADC */

/* 静态变量 */
static struct rt_device_pwm *pwm_dev = NULL;
static uint8_t current_brightness = 80;
static uint8_t saved_brightness = 80;  /* 保存关闭前的亮度值 */
static uint8_t min_brightness = DEFAULT_MIN_BRIGHTNESS;
static bool auto_brightness_enabled = false;
static bool backlight_on = true;        /* 背光状态 */
static rt_thread_t auto_brightness_thread = NULL;

/**
 * @brief 将光感值映射到亮度值
 *
 * @param light_value 光感值
 * @return uint8_t 亮度值 (0-100)
 */
static uint8_t light_to_brightness(uint32_t light_value)
{
    uint8_t brightness;

    /* 光感值越小表示环境越暗 */
    /* 映射公式：亮度 = 最小值 + (光感值 / 最大光感值) * (100 - 最小值) */
    brightness = min_brightness +
                 ((light_value * (100 - min_brightness)) / LIGHT_SENSOR_MAX);

    LOG_D("Light value: %d -> Brightness: %d", light_value, brightness);

    return brightness;
}

/**
 * @brief 设置PWM背光亮度
 *
 * @param brightness 亮度值 (0-100)
 * @return int 0表示成功，负数表示失败
 */
static int set_pwm_brightness(uint8_t brightness)
{
    rt_err_t ret;
    uint32_t pulse_width;

    if (pwm_dev == NULL) {
        LOG_E("PWM device not initialized");
        return -RT_ERROR;
    }

    /* 亮度值范围检查 */
    if (brightness > 100) {
        brightness = 100;
    }

    /* PWM频率: 1KHz = 1000000ns */
    /* 占空比 = brightness / 100 */
    pulse_width = (10000 * brightness);  /* 1000000ns * brightness / 100 = 10000 * brightness */

    ret = rt_pwm_set(pwm_dev, AIC_PWM_BACKLIGHT_CHANNEL, 1000000, pulse_width);
    if (ret != RT_EOK) {
        LOG_E("Failed to set PWM brightness, ret: %d", ret);
        return ret;
    }

    current_brightness = brightness;
    LOG_I("Set brightness: %d%%", brightness);

    return RT_EOK;
}

/**
 * @brief 自动亮度调节线程
 *
 * @param parameter 线程参数
 */
static void auto_brightness_thread_entry(void *parameter)
{
    rt_err_t ret;
    uint32_t light_value;
    uint8_t brightness;

    LOG_I("Auto brightness thread started");

    while (auto_brightness_enabled) {
        /* 读取光感值 */
        ret = light_sener_read(&light_value);
        if (ret != RT_EOK) {
            LOG_W("Failed to read light sensor, retrying...");
            rt_thread_mdelay(AUTO_BRILLIANCE_UPDATE_INTERVAL);
            continue;
        }

        /* 将光感值映射到亮度值 */
        brightness = light_to_brightness(light_value);

        /* 设置亮度 */
        ret = set_pwm_brightness(brightness);
        if (ret != RT_EOK) {
            LOG_W("Failed to set brightness");
        }

        /* 等待下次更新 */
        rt_thread_mdelay(AUTO_BRILLIANCE_UPDATE_INTERVAL);
    }

    LOG_I("Auto brightness thread stopped");
}

/**
 * @brief 亮度控制初始化
 *
 * @return int 0表示成功，负数表示失败
 */
int brilliance_init(void)
{
    rt_err_t ret;

    /* 查找PWM设备 */
    pwm_dev = (struct rt_device_pwm *)rt_device_find(PWM_DEVICE_NAME);
    if (pwm_dev == NULL) {
        LOG_E("Failed to find PWM device %s", PWM_DEVICE_NAME);
        return -RT_ERROR;
    }

    /* 初始化光感传感器 */
    ret = light_sener_init();
    if (ret != RT_EOK) {
        LOG_W("Failed to initialize light sensor, auto brightness will not work");
    }

    /* 启用PWM通道 */
    ret = rt_pwm_enable(pwm_dev, AIC_PWM_BACKLIGHT_CHANNEL);
    if (ret != RT_EOK) {
        LOG_E("Failed to enable PWM channel %d, ret: %d", AIC_PWM_BACKLIGHT_CHANNEL, ret);
        return ret;
    }

    /* 设置初始亮度 */
    ret = set_pwm_brightness(current_brightness);
    if (ret != RT_EOK) {
        LOG_E("Failed to set initial brightness");
        return ret;
    }

    LOG_I("Brilliance control initialized successfully");
    return RT_EOK;
}

/**
 * @brief 设置亮度值
 *
 * @param brightness 亮度值 (0-100)
 * @return int 0表示成功，负数表示失败
 */
int brilliance_set_brightness(uint8_t brightness)
{
    if (brightness > 100) {
        LOG_W("Brightness value %d out of range, clamping to 100", brightness);
        brightness = 100;
    }

    /* 如果启用了自动亮度调节，先禁用 */
    if (auto_brightness_enabled) {
        LOG_W("Auto brightness is enabled, disabling it");
        brilliance_auto_disable();
    }

    return set_pwm_brightness(brightness);
}

/**
 * @brief 获取当前亮度值
 *
 * @param brightness 存储亮度值的指针
 * @return int 0表示成功，负数表示失败
 */
int brilliance_get_brightness(uint8_t *brightness)
{
    if (brightness == NULL) {
        LOG_E("Invalid parameter");
        return -RT_ERROR;
    }

    *brightness = current_brightness;
    return RT_EOK;
}

/**
 * @brief 启用自动亮度调节
 *
 * @return int 0表示成功，负数表示失败
 */
int brilliance_auto_enable(void)
{
    rt_err_t ret;

    if (auto_brightness_enabled) {
        LOG_W("Auto brightness is already enabled");
        return RT_EOK;
    }

    /* 检查光感传感器是否初始化 */
    /* 如果未初始化，尝试初始化 */
    /* 这里不强制要求光感传感器，允许软错误 */

    auto_brightness_enabled = true;

    /* 创建并启动自动亮度调节线程 */
    auto_brightness_thread = rt_thread_create("auto_brilliance",
                                              auto_brightness_thread_entry,
                                              NULL,
                                              AUTO_BRILLIANCE_THREAD_STACK_SIZE,
                                              AUTO_BRILLIANCE_THREAD_PRIORITY,
                                              20);
    if (auto_brightness_thread == NULL) {
        LOG_E("Failed to create auto brightness thread");
        auto_brightness_enabled = false;
        return -RT_ERROR;
    }

    ret = rt_thread_startup(auto_brightness_thread);
    if (ret != RT_EOK) {
        LOG_E("Failed to start auto brightness thread, ret: %d", ret);
        rt_thread_delete(auto_brightness_thread);
        auto_brightness_thread = NULL;
        auto_brightness_enabled = false;
        return ret;
    }

    LOG_I("Auto brightness enabled");
    return RT_EOK;

