struct aic_panel *aic_find_panel(u32 connector_type) {
  int i;

  for (i = 0; i < ARRAY_SIZE(panels); i++) {
    if (panels[i]->connector_type == connector_type) {
      break;
    }
  }

  if (i >= ARRAY_SIZE(panels))
    return NULL;

  pr_debug("find panel driver : %s\n", panels[i]->name);

  return panels[i];
}

