  u8 *p;
  u8 num, code;

  for (p = para_cmd; p < (para_cmd + size);) {
    num = *p++ - 1;
    code = *p++;

    if (num == 0)
      aic_delay_ms((u32)code);
    else
      panel->callbacks.di_send_cmd((u32)code, 0, p, num);

    p += num;
  }
}

